<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue'
const props=defineProps<{initial?:{drum_signals:number}}>(),emit=defineEmits<{hit:[];change:[payload:{drum_signals:number}];complete:[payload:{drum_signals:number}]}>(),beats=ref(props.initial?.drum_signals||0),struck=ref(false)
let timer:ReturnType<typeof setTimeout>
let lastHit=-Infinity
function hit(event?:MouseEvent|KeyboardEvent){const now=performance.now();if(('repeat' in (event||{})&&(event as KeyboardEvent).repeat)||now-lastHit<110)return;lastHit=now;beats.value++;struck.value=true;emit('hit');emit('change',{drum_signals:beats.value});clearTimeout(timer);timer=setTimeout(()=>struck.value=false,180)}
onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><section class="drum-stage" :class="{struck}"><div class="drum-vignette"></div><header><span>三 · 寨前传号</span><h2>让鼓声穿过江雾</h2><p>诸葛亮抬手示意。三通鼓后，先听寨里怎样回应。</p></header><button class="drum-head" @click="hit" @keydown.space.prevent="hit" aria-label="击打船头战鼓"><span>{{beats?'再击一通':'击鼓'}}</span></button><div class="drum-echo" :key="beats" v-if="beats"></div><footer><p>{{Math.min(beats,3)}} / 3 通 · {{beats>=3?'鼓令已传，收槌听江。':'点鼓面，或聚焦后按空格。'}}</p><button class="gold" :disabled="beats<3" @click="emit('complete',{drum_signals:beats})">收槌，听候寨中动静</button></footer></section></template>
<style scoped>.drum-stage{position:absolute;inset:0;background:#071822 url('/v12/drum-deck.webp') center/cover}.drum-vignette{position:absolute;inset:0;background:linear-gradient(90deg,#04111bcb,transparent 72%),linear-gradient(0deg,#03101a,transparent 40%)}header{position:absolute;top:15%;left:6%;max-width:440px}header span{color:#ccb27b;font-size:12px;letter-spacing:.2em}header h2{font:38px SimSun;color:#f1e3c3;line-height:1.4}header p{line-height:1.8;color:#bacbd1;max-width:340px}.drum-head{position:absolute;left:53%;top:18%;width:30%;height:60%;border-radius:50%;background:transparent!important;color:#ffe0a9!important;border:2px solid #d8b274aa!important;box-shadow:0 0 45px #e8b46333;transform:rotate(-12deg);transition:transform .12s}.drum-head span{display:inline-block;padding:12px 20px;background:#161714ba;border-radius:30px;transform:rotate(12deg);font-size:18px}.struck .drum-head{transform:rotate(-12deg) scale(.975);box-shadow:0 0 90px #f7c57666}.drum-echo{pointer-events:none;position:absolute;left:68%;top:47%;width:50px;height:50px;border:1px solid #dbbe7e;border-radius:50%;animation:echo .7s ease-out forwards}footer{position:absolute;bottom:5%;left:6%;right:6%;display:flex;justify-content:space-between;align-items:center;gap:16px}footer p{color:#d6d0b9}button:disabled{opacity:.3}@keyframes echo{to{transform:translate(-50%,-50%) scale(12);opacity:0}}@media(max-width:700px){header{top:10%;max-width:85%}header h2{font-size:28px}.drum-head{left:32%;top:37%;width:58%;height:35%}footer{flex-direction:column;align-items:flex-start}}@media(prefers-reduced-motion:reduce){.drum-echo{animation:none;display:none}.drum-head{transition:none}}</style>
